arguments.command:
python3 -c "
import json
m=json.load(open('tests/manifest.json'))
print(type(m), list(m.keys()) if isinstance(m,dict) else len(m))
print(json.dumps({k:v for k,v in m.items() if not isinstance(v,(list,dict))}, indent=1)[:2000])
for k,v in m.items():
    if isinstance(v,list): print(k,'LIST',len(v))
    elif isinstance(v,dict): print(k,'DICT',list(v.keys())[:20])
"

